import numpy as np
from scipy import stats
from sklearn.metrics import roc_auc_score
from sklearn.linear_model import LogisticRegression
from collections import defaultdict

MAX_DRIVERS = 3

def design(feats):
    # Identify strong candidates based on t-statistics and AUC
    candidates = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'clinical' or feats.types[i] == 'expression':
            t_stat = feats.x[:, i].T @ (feats.y * 2 - 1)
            auc = roc_auc_score(feats.y, feats.x[:, i])
            candidates.append((fid, abs(t_stat), auc))

    # Sort by t-statistic magnitude
    candidates.sort(key=lambda x: x[1], reverse=True)

    # Remove near-duplicates based on correlation
    keep = []
    correlations = {}
    for i, (fid1, _, _) in enumerate(candidates):
        is_duplicate = False
        for fid2 in keep:
            if (fid1, fid2) in correlations or (fid2, fid1) in correlations:
                if abs(correlations.get((fid1, fid2), correlations.get((fid2, fid1), 0))) >= 0.6:
                    is_duplicate = True
                    break
            else:
                corr = np.corrcoef(feats.x[:, feats.column(fid1)], feats.x[:, feats.column(fid2)])[0, 1]
                correlations[(fid1, fid2)] = corr
                if abs(corr) >= 0.6:
                    is_duplicate = True
                    break
        if not is_duplicate:
            keep.append(fid1)

    # Select top candidates
    top_candidates = keep[:MAX_DRIVERS * 2]

    # Look for interaction terms
    best_product = None
    best_auc = 0.5

    for i, fid1 in enumerate(top_candidates):
        for j, fid2 in enumerate(top_candidates[i+1:], i+1):
            # Create product feature
            col1 = feats.column(fid1)
            col2 = feats.column(fid2)
            prod = feats.x[:, col1] * feats.x[:, col2]

            # Fit logistic regression with product term
            X = np.column_stack([feats.x[:, col1], feats.x[:, col2], prod])
            lr = LogisticRegression(fit_intercept=True, max_iter=1000)
            lr.fit(X, feats.y)
            y_pred = lr.predict_proba(X)[:, 1]
            auc = roc_auc_score(feats.y, y_pred)

            if auc > best_auc:
                best_auc = auc
                best_product = (fid1, fid2)

    # If we found a good product term, return it
    if best_product and best_auc > 0.55:
        return Design(
            drivers=(best_product[0], best_product[1]),
            columns=(best_product[0], best_product[1]),
            products=(best_product,),
            loadings={}
        )

    # Otherwise, return the strongest single feature
    if top_candidates:
        return Design(
            drivers=(top_candidates[0],),
            columns=(top_candidates[0],),
            products=(),
            loadings={top_candidates[0]: 1.0}
        )

    return Design(drivers=(), columns=(), products=(), loadings={})

